window.SLIDES_HTML = "<div class=\"slide\" id=\"s-opening-1\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">All I have to offer in prayer is myself.<br><br><span class=\"hw\" style=\"font-style:italic;font-weight:700\">Sometimes I cannot find the ‎רוּחַ‎ to pray alone.</span></div><div class=\"box dots\">●○○○○○○</div></div>\n<div class=\"slide\" id=\"s-opening-2\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">As two people walking together through a dark wood <br>feel stronger and braver for each other’s presence,<br><br><span class=\"hw\" style=\"font-style:italic;font-weight:700\">so I find spiritual strength in communal ‎תְּפִלָּה‎.</span></div><div class=\"box dots\">○●○○○○○</div></div>\n<div class=\"slide\" id=\"s-opening-3\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">We want to stand here, ready in body and mind, <br>to take upon ourselves the mitzvah, <br>“You shall love your fellow human being as yourself.” <br><br><span style=\"font-style:italic;font-weight:700\">We want to take upon ourselves the mitzvah, </span><br><span style=\"font-style:italic;font-weight:700\">“You shall not separate yourself from the community.” </span></div><div class=\"box dots\">○○●○○○○</div></div>\n<div class=\"slide\" id=\"s-opening-4\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">I enter ‎<span class=\"hw\" style=\"font-size:calc(var(--pt)*48)\">תְּפִלָּה</span>‎ as an individual, <br>but I become a part of a ‎<span class=\"hw\" style=\"font-size:calc(var(--pt)*48)\">קְהִלָּה</span>‎ ‎<span class=\"hw\" style=\"font-size:calc(var(--pt)*48)\">קְדוֹשָׁה</span>‎.<br><br><span style=\"font-style:italic;font-weight:700\">As a ‎</span><span class=\"hw\" style=\"font-size:calc(var(--pt)*48);font-style:italic;font-weight:700\">קְהִלָּה</span><span style=\"font-style:italic;font-weight:700\">‎ ‎</span><span class=\"hw\" style=\"font-size:calc(var(--pt)*48);font-style:italic;font-weight:700\">קְדוֹשָׁה</span><span style=\"font-style:italic;font-weight:700\">‎</span><span style=\"font-style:italic;font-weight:700\">, we will be </span><br><span style=\"font-style:italic;font-weight:700\">a welcoming and friendly place, </span><br><span style=\"font-style:italic;font-weight:700\">filled with enthusiastic song </span><br><span style=\"font-style:italic;font-weight:700\">and intentional silence.</span></div><div class=\"box dots\">○○○●○○○</div></div>\n<div class=\"slide\" id=\"s-opening-5\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">May our communal ‎<span class=\"hw\" style=\"font-size:calc(var(--pt)*48)\">תְּפִלָּה</span>‎ illuminate all that is awesome <br>within and around us.<br><br><span style=\"font-style:italic;font-weight:700\">May our communal ‎</span><span class=\"hw\" style=\"font-size:calc(var(--pt)*48);font-style:italic;font-weight:700\">תְּפִלָּה</span><span style=\"font-style:italic;font-weight:700\">‎ </span><span style=\"font-style:italic;font-weight:700\">strengthen the ties that bind us together.</span></div><div class=\"box dots\">○○○○●○○</div></div>\n<div class=\"slide\" id=\"s-opening-6\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Let us rejoice together in times of joy.<br><br><span style=\"font-style:italic;font-weight:700\">Let us support one another in times of sorrow.</span></div><div class=\"box dots\">○○○○○●○</div></div>\n<div class=\"slide\" id=\"s-opening-7\"><div class=\"box h-he he\">קְרִיאָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Opening Reading</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Help us find holiness in our lives and wholeness in our world.<br><br><span style=\"font-style:italic;font-weight:700\">And may our ‎</span><span class=\"hw\" style=\"font-size:calc(var(--pt)*48);font-style:italic;font-weight:700\">תְּפִלָּה</span><span style=\"font-style:italic;font-weight:700\">‎ </span><span style=\"font-style:italic;font-weight:700\">demonstrate ‎</span><span class=\"hw\" style=\"font-size:calc(var(--pt)*48);font-style:italic;font-weight:700\">כָּבוֹד</span><span style=\"font-style:italic;font-weight:700\">‎ </span><span style=\"font-style:italic;font-weight:700\">to ourselves, </span><br><span style=\"font-style:italic;font-weight:700\">to one another, and to God.</span></div><div class=\"box dots\">○○○○○○●</div></div>\n<div class=\"slide\" id=\"s-rocks-1\"><div class=\"box h-he he\">אֲבָנִים</div><div class=\"box h-en\"><span style=\"font-weight:700\">Rock Counting</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Limnot yameinu<br>kein hoda,<br>v’navi l’vav chochmah.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Teach us to count our days, so that we may acquire a wise and loving heart.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">לִמְנוֹת יָמֵינוּ</span><br><span class=\"hw\">כֵּן הוֹדַע,</span><br><span class=\"hw\">וְנָבִא לְבַב חָכְמָה.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;top:calc(var(--in)*3.96)\">— Psalm 90:12</div></div>\n<div class=\"slide\" id=\"s-modeh-1\"><div class=\"box h-he he\">מוֹדֶה אֲנִי</div><div class=\"box h-en\"><span style=\"font-weight:700\">Modeh Ani</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Modeh ani l’fanecha,<br>Melech chai v’kayam,<br>shehechezarta bi nishmati<br>b’chemlah, rabah emunatecha.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">I offer thanks to You, ever-living Sovereign, that You have restored my soul to me. How great is Your trust.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">מוֹדֶה אֲנִי לְפָנֶיךָ,</span><br><span class=\"hw\">מֶלֶךְ חַי וְקַיָּם,</span><br><span class=\"hw\">שֶׁהֶחֱזַרְתָּ בִּי נִשְׁמָתִי</span><br><span class=\"hw\">בְּחֶמְלָה רַבָּה אֱמוּנָתֶךָ.</span></div></div>\n<div class=\"slide\" id=\"s-mahtovu-1\"><div class=\"box h-en\">Mah Tovu</div><div class=\"box h-he he\">מַה טֹּבוּ</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">Mah tovu ohalecha, Ya’akov,<br>mishk’notecha, Yisrael!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">מַה־טֹּבוּ אֹהָלֶיךָ יַעֲקֹב,</span><br><span class=\"hw\">מִשְׁכְּנֹתֶיךָ יִשְׂרָאֵל!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">How good are your tents, O Jacob, your dwelling places, O Israel!</div></div>\n<div class=\"slide\" id=\"s-asher-1\"><div class=\"box h-he he\">אֲשֶׁר יָצַר</div><div class=\"box h-en\"><span style=\"font-weight:700\">Asher Yatzar</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Baruch atah, Adonai,<br>Eloheinu Melech haolam,<br><br>asher yatzar et ha-adam<br>b’chochmah,<br>uvara vo <br>n’kavim n’kavim,<br>chalulim chalulim.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם,</span><br><br><span class=\"hw\">אֲשֶׁר </span><span class=\"hw\">יָצַר אֶת הָאָדָם</span><br><span class=\"hw\">בְּחָכְמָה</span>,<br><span class=\"hw\">וּבָרָא בוֹ </span><br><span class=\"hw\">נְקָבִים נְקָבִים,</span><br><span class=\"hw\">חֲלוּלִים חֲלוּלִים.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Blessed are You, Adonai our God, Sovereign of the universe, who formed the human body with wisdom, creating within it openings upon openings, hollows upon hollows.</div><div class=\"box dots\">●○</div></div>\n<div class=\"slide\" id=\"s-asher-2\"><div class=\"box h-he he\">אֲשֶׁר יָצַר</div><div class=\"box h-en\"><span style=\"font-weight:700\">Asher Yatzar</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Galui v’yadua<br>lifnei chisei ch’vodecha,<br>she-im yipatei-ach echad meihem,<br>o yisateim echad meihem,<br>i efshar l’hitkayeim<br>v’laamod l’fanecha.<br>Baruch atah, Adonai,<br>rofei chol basar<br>umafli laasot.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">גָּלוּי וְיָדוּעַ</span><br><span class=\"hw\">לִפְנֵי </span><span class=\"hw\">כִסֵּא</span> <span class=\"hw\">כְבוֹדֶךָ</span>,<br><span class=\"hw\">שֶׁאִם יִפָּתֵחַ אֶחָד </span><span class=\"hw\">מֵהֶם</span>,<br><span class=\"hw\">אוֹ יִסָּתֵם אֶחָד </span><span class=\"hw\">מֵהֶם</span>,<br><span class=\"hw\">אִי אֶפְשַׁר </span><span class=\"hw\">לְהִתְקַיֵּם</span><br><span class=\"hw\">וְלַעֲמֹד </span><span class=\"hw\">לְפָנֶיךָ</span>.<br><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">רוֹפֵא כָל בָּשָׂר</span><br><span class=\"hw\">וּמַפְלִיא לַעֲשׂוֹת.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">It is clear and known before Your throne of glory that if just one of them were to open, or one of them were to close, it would be impossible to survive and stand before You. Blessed are You, Adonai, who heals all flesh and works wonders.</div><div class=\"box dots\">○●</div></div>\n<div class=\"slide\" id=\"s-elohai-1\"><div class=\"box h-en\">Elohai N’shamah</div><div class=\"box h-he he\">אֱלֹהַי נְשָׁמָה</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">Elohai, n’shamah shenatata bi<br>t’horah hi.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">אֱלֹהַי, נְשָׁמָה שֶׁנָּתַתָּ בִּי</span><br><span class=\"hw\">טְהוֹרָה הִיא.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">My God, the soul You have given me is pure.</div></div>\n<div class=\"slide\" id=\"s-laasok-1\"><div class=\"box h-he he\">לַעֲסֹק בְּדִבְרֵי תוֹרָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Laasok B’divrei Torah</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Baruch Atah Adonai,<br>Eloheinu Melech ha-olam,<br>asher kid’shanu b’mitzvotav,<br>v’tzivanu laasok<br>b’divrei Torah.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם,</span><br><span class=\"hw\">אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו</span><br><span class=\"hw\">וְצִוָּנוּ לַעֲסֹק</span><br><span class=\"hw\">בְּדִבְרֵי תוֹרָה.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.9)\">Blessed are You, Adonai our God, Sovereign of the universe, who makes us holy with mitzvot and commands us to engage with words of Torah.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*20);line-height:calc(var(--pt)*24);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\"><span style=\"font-style:italic\">from Menschology</span></div></div>\n<div class=\"slide\" id=\"s-eilu-1\"><div class=\"box h-he he\">אֵלּוּ דְבָרִים</div><div class=\"box h-en\"><span style=\"font-weight:700\">Eilu D’varim</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Eilu d’varim<br>she-ein lahem shiur,<br>she-adam ocheil peiroteihem<br>baolam hazeh,<br>v’hakeren kayemet lo<br>laolam haba.<br>V’eilu hein:</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">אֵלּוּ דְבָרִים</span><br><span class=\"hw\">שֶׁאֵין לָהֶם שִׁעוּר,</span><br><span class=\"hw\">שֶׁאָדָם אוֹכֵל פֵּרוֹתֵיהֶם</span><br><span class=\"hw\">בָּעוֹלָם הַזֶּה,</span><br><span class=\"hw\">וְהַקֶּרֶן קַיֶּמֶת לוֹ</span><br><span class=\"hw\">לָעוֹלָם הַבָּא.</span><br><span class=\"hw\">וְאֵלּוּ הֵן:</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*7.39);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.37)\">These are things that have no limit: we enjoy their fruit in this world, and the main reward remains for us in the world to come. And these are they:</div><div class=\"box dots\">●○○○</div></div>\n<div class=\"slide\" id=\"s-eilu-2\"><div class=\"box h-he he\">אֵלּוּ דְבָרִים</div><div class=\"box h-en\"><span style=\"font-weight:700\">Eilu D’varim</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*8.51);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*9.36)\"><span class=\"hw\">וְהַכְנָסַת אוֹרְחִים</span><br><span style=\"font-size:calc(var(--pt)*26)\">v’hachnasat orchim</span><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">welcoming guests</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*3.12);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*9.33)\"><span class=\"hw\">וּבִקּוּר חוֹלִים</span><br><span style=\"font-size:calc(var(--pt)*26)\">uvikur cholim</span><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">visiting the sick</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*11.2);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*3.54)\"><span class=\"hw\">כִּבּוּד אָב וָאֵם</span><br><span style=\"font-size:calc(var(--pt)*26)\">kibud av va-eim</span><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">honoring parents</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*22);line-height:calc(var(--pt)*40);left:calc(var(--in)*5.82);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*3.57)\"><span class=\"hw\" style=\"font-size:calc(var(--pt)*32)\">וּגְמִילוּת חֲסָדִים</span><br><span style=\"font-size:calc(var(--pt)*26)\">ug’milut chasadim</span><br><span style=\"font-style:italic\">acts of loving-kindness</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*0.47);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*3.57)\"><span class=\"hw\">וְהַשְׁכָּמַת בֵּית הַמִּדְרָשׁ שַׁחֲרִית וְעַרְבִית</span><br><span style=\"font-size:calc(var(--pt)*26)\">v’hashkamat beit hamidrash shacharit v’arvit</span><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">Studying early and late</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*11.23);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*1.2)\"><span style=\"font-weight:700\">1</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*5.85);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*1.23)\"><span style=\"font-weight:700\">2</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*0.5);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*1.23)\"><span style=\"font-weight:700\">3</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*8.54);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*7.02)\"><span style=\"font-weight:700\">4</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*3.15);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*6.99)\"><span style=\"font-weight:700\">5</span></div><div class=\"box dots\">○●○○</div></div>\n<div class=\"slide\" id=\"s-eilu-3\"><div class=\"box h-he he\">אֵלּוּ דְבָרִים</div><div class=\"box h-en\"><span style=\"font-weight:700\">Eilu D’varim</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*22);line-height:calc(var(--pt)*40);left:calc(var(--in)*8.49);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*3.76)\"><span class=\"hw\" style=\"font-size:calc(var(--pt)*32)\">וְהַכְנָסַת כַּלָּה</span><br><span style=\"font-size:calc(var(--pt)*26)\">v’hachnasat kalah</span><br><span style=\"font-style:italic\">celebrating with a bride and groom</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*22);line-height:calc(var(--pt)*40);left:calc(var(--in)*3.15);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*3.76)\"><span class=\"hw\" style=\"font-size:calc(var(--pt)*32)\">וּלְוָיַת הַמֵּת</span><br><span style=\"font-size:calc(var(--pt)*26)\">ul’vayat hameit</span><br><span style=\"font-style:italic\">attending a funeral</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*8.49);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*8.16)\"><span class=\"hw\">וְעִיּוּן תְּפִלָּה</span><br><br><span style=\"font-size:calc(var(--pt)*26)\">v’iyun</span><span style=\"font-size:calc(var(--pt)*26)\"> t’filah</span><br><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">praying with intent</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*32);line-height:calc(var(--pt)*40);left:calc(var(--in)*3.15);width:calc(var(--in)*4.71);text-align:center;white-space:normal;direction:rtl;top:calc(var(--in)*8.16)\"><span class=\"hw\">וַהֲבָאַת שָׁלוֹם </span><br><span class=\"hw\">בֵּין אָדָם לַחֲבֵרוֹ</span><br><span style=\"font-size:calc(var(--pt)*26)\">vahavaat shalom </span><br><span style=\"font-size:calc(var(--pt)*26)\">bein</span><span style=\"font-size:calc(var(--pt)*26)\"> adam lachaveiro</span><br><span style=\"font-size:calc(var(--pt)*22);font-style:italic\">making peace between people</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*8.53);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*1.42)\"><span style=\"font-weight:700\">6</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*3.17);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*1.42)\"><span style=\"font-weight:700\">7</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*8.53);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*5.82)\"><span style=\"font-weight:700\">8</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*24);line-height:calc(var(--pt)*28.8);left:calc(var(--in)*3.17);width:calc(var(--in)*1);text-align:center;white-space:normal;top:calc(var(--in)*5.82)\"><span style=\"font-weight:700\">9</span></div><div class=\"box dots\">○○●○</div></div>\n<div class=\"slide\" id=\"s-eilu-4\"><div class=\"box h-he he\">אֵלּוּ דְבָרִים</div><div class=\"box h-en\"><span style=\"font-weight:700\">Eilu D’varim</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">V’talmud Torah k’neged kulam.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">וְתַלְמוּד תּוֹרָה כְּנֶגֶד כֻּלָּם.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);width:calc(var(--in)*7.63);text-align:center;white-space:normal;top:calc(var(--in)*2.21)\">And the study of Torah is equal to them all.<br><span style=\"font-style:italic\">(Because it leads to them all.)</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*88);line-height:calc(var(--pt)*105.6);left:calc(var(--in)*7.53);top:calc(var(--in)*5.94)\">=&gt;</div><div class=\"box dots\">○○○●</div></div>\n<div class=\"slide\" id=\"s-psalm150-1\"><div class=\"box h-he he\">הַלְלוּיָהּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Halleluyah (Psalm 150)</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Halleluyah! Hallelu El b’kodsho,<br>halleluhu birkia uzo.<br>Halleluhu bigvurotav,<br>halleluhu k’rov gudlo.<br>Halleluhu b’teika shofar,<br>halleluhu b’neivel v’chinor.<br>Halleluyah, Halleluyah,<br>Halleluyah, Hallelu-yah!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">הַלְלוּיָהּ! הַלְלוּ אֵל בְּקׇדְשׁוֹ,</span><br><span class=\"hw\">הַלְלוּהוּ בִּרְקִיעַ עֻזּוֹ.</span><br><span class=\"hw\">הַלְלוּהוּ בִגְבוּרֹתָיו,</span><br><span class=\"hw\">הַלְלוּהוּ כְּרֹב גֻּדְלוֹ.</span><br><span class=\"hw\">הַלְלוּהוּ בְּתֵקַע שׁוֹפָר,</span><br><span class=\"hw\">הַלְלוּהוּ בְּנֵבֶל וְכִנּוֹר.</span><br><span class=\"hw\">הַלְלוּיָהּ, הַלְלוּיָהּ,</span><br><span class=\"hw\">הַלְלוּיָהּ, הַלְלוּיָהּ!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.25)\">Halleluyah! Praise God in the sanctuary; <br>praise God in the mighty heavens.<br>Praise God for mighty deeds and surpassing greatness.<br>Praise with shofar blasts, with harp and lyre.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*14);line-height:calc(var(--pt)*16.8);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*10.55)\"><span style=\"font-style:italic\">Psalm 150 · sung to the tune of Leonard Cohen’s “Hallelujah”</span></div><div class=\"box dots\">●○</div></div>\n<div class=\"slide\" id=\"s-psalm150-2\"><div class=\"box h-he he\">הַלְלוּיָהּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Halleluyah (Psalm 150)</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Halleluhu b’tof umachol,<br>halleluhu b’minim v’ugav.<br>Halleluhu b’tziltz’lei shama,<br>halleluhu b’tziltz’lei t’ruah.<br>Kol han’shamah t’hallel Yah,<br>Halleluyah!<br>Halleluyah, Halleluyah,<br>Halleluyah, Hallelu-yah!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">הַלְלוּהוּ בְּתֹף וּמָחוֹל,</span><br><span class=\"hw\">הַלְלוּהוּ בְּמִנִּים וְעֻגָב.</span><br><span class=\"hw\">הַלְלוּהוּ בְצִלְצְלֵי שָׁמַע,</span><br><span class=\"hw\">הַלְלוּהוּ בְּצִלְצְלֵי תְרוּעָה.</span><br><span class=\"hw\">כֹּל הַנְּשָׁמָה תְּהַלֵּל יָהּ,</span><br><span class=\"hw\">הַלְלוּיָהּ!</span><br><span class=\"hw\">הַלְלוּיָהּ, הַלְלוּיָהּ,</span><br><span class=\"hw\">הַלְלוּיָהּ, הַלְלוּיָהּ!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.25)\">Praise with drum and dance, with strings and flute.<br>Praise with resounding cymbals, with clashing cymbals.<br>Let every breath praise God. Halleluyah!</div><div class=\"box\" style=\"font-size:calc(var(--pt)*14);line-height:calc(var(--pt)*16.8);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*10.55)\"><span style=\"font-style:italic\">Psalm 150 · sung to the tune of Leonard Cohen’s “Hallelujah”</span></div><div class=\"box dots\">○●</div></div>\n<div class=\"slide\" id=\"s-barchu-1\"><div class=\"box h-he he\">בָּרְכוּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Bar’chu</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Bar’chu et Adonai ham’vorach!<br>Baruch Adonai ham’vorach<br>l’olam va-ed!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">בָּרְכוּ אֶת יְיָ הַמְבֹרָךְ!</span><br><span class=\"hw\">בָּרוּךְ יְיָ הַמְבֹרָךְ</span><br><span class=\"hw\">לְעוֹלָם וָעֶד!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Praise Adonai to whom praise is due forever! <br>Praised be Adonai to whom praise is due, now and forever!</div></div>\n<div class=\"slide\" id=\"s-yotzeir-1\"><div class=\"box h-en\">Yotzeir Or</div><div class=\"box h-he he\">יוֹצֵר אוֹר</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">Baruch atah, Adonai,<br>Eloheinu Melech haolam,<br>yotzeir or uvorei choshech,<br>oseh shalom uvorei et hakol.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם,</span><br><span class=\"hw\">יוֹצֵר אוֹר וּבוֹרֵא חֹשֶׁךְ,</span><br><span class=\"hw\">עֹשֶׂה שָׁלוֹם וּבוֹרֵא אֶת הַכֹּל.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Blessed are You, Adonai our God, Sovereign of the universe, Creator of light and darkness, who makes peace and fashions all things.</div><div class=\"box dots\">●○</div></div>\n<div class=\"slide\" id=\"s-yotzeir-2\"><div class=\"box h-en\">Yotzeir Or</div><div class=\"box h-he he\">יוֹצֵר אוֹר</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\"><span class=\"hl\">Mah rabu maasecha, Adonai!</span><br><span class=\"hl\">Kulam b’chochmah asita,</span><br><span class=\"hl\">mal’ah haaretz kinyanecha.</span><br><br>Baruch atah, Adonai,<br>yotzeir ham’orot.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw hl\">מָה רַבּוּ מַעֲשֶׂיךָ יְיָ!</span><br><span class=\"hw hl\">כֻּלָּם בְּחָכְמָה עָשִׂיתָ,</span><br><span class=\"hw hl\">מָלְאָה הָאָרֶץ קִנְיָנֶךָ.</span><br><br><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">יוֹצֵר הַמְּאוֹרוֹת.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">How many are the things You have made, Adonai! In wisdom You made them all; the earth is full of Your creations. Blessed are You, Adonai, Creator of the lights.</div><div class=\"box dots\">○●</div></div>\n<div class=\"slide\" id=\"s-shma-1\"><div class=\"box h-he he\">שְׁמַע</div><div class=\"box h-en\"><span style=\"font-weight:700\">Sh’ma</span></div><div class=\"box he\" style=\"font-size:calc(var(--pt)*60);line-height:calc(var(--pt)*72);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;top:calc(var(--in)*1.7)\"><span class=\"hw\">שְׁמַע יִשְׂרָאֵל, יְיָ אֱלֹהֵינוּ, יְיָ אֶחָד!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;top:calc(var(--in)*3)\">Sh’ma Yisrael, Adonai Eloheinu, Adonai Echad!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;top:calc(var(--in)*4.6)\"><span class=\"hw\">בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*36);line-height:calc(var(--pt)*43.2);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;top:calc(var(--in)*5.55)\">Baruch shem k’vod malchuto l’olam va-ed.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*.45);right:calc(var(--in)*.45);text-align:center;bottom:calc(var(--in)*0.27)\">Hear O Israel, Adonai is our God, Adonai is One! <br>Blessed is God’s glorious majesty, forever and ever.</div></div>\n<div class=\"slide\" id=\"s-vahavta-1\"><div class=\"box h-he he\">וְאָהַבְתָּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">V’ahavta</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\"><span style=\"font-weight:700\">V’ahavta et Adonai Elohecha</span><br>b’chol l’vav’cha,<br>uv’chol nafsh’cha,<br>uv’chol m’odecha.<br>V’hayu had’varim ha-eileh<br>asher anochi m’tzav’cha hayom<br>al l’vavecha.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\" style=\"font-weight:700\">וְאָהַבְתָּ אֵת יְיָ אֱלֹהֶיךָ</span><br><span class=\"hw\">בְּכׇל־לְבָבְךָ</span><br><span class=\"hw\">וּבְכׇל־נַפְשְׁךָ</span><br><span class=\"hw\">וּבְכׇל־מְאֹדֶךָ.</span><br><span class=\"hw\">וְהָיוּ הַדְּבָרִים הָאֵלֶּה</span><br><span class=\"hw\">אֲשֶׁר אָנֹכִי מְצַוְּךָ הַיּוֹם</span><br><span class=\"hw\">עַל־לְבָבֶךָ.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">You shall love Adonai your God with all your heart, with all your soul, and with all your might. Place the words I command you today on your heart.</div><div class=\"box dots\">●○○</div></div>\n<div class=\"slide\" id=\"s-vahavta-2\"><div class=\"box h-he he\">וְאָהַבְתָּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">V’ahavta</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\"><span style=\"font-weight:700\">V’shinantam l’vanecha</span><br>v’dibarta bam<br>b’shivt’cha b’veitecha<br>uv’lecht’cha vaderech<br><span style=\"font-weight:700\">uv’shochb’cha uv’kumecha</span>.<br><span style=\"font-weight:700\">Uk’shartam l’ot al yadecha</span>,<br><span style=\"font-weight:700\">v’hayu l’totafot bein einecha</span>.<br><span style=\"font-weight:700\">Uch’tavtam al m’zuzot</span><br><span style=\"font-weight:700\">beitecha uvisharecha</span>.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\" style=\"font-weight:700\">וְשִׁנַּנְתָּם לְבָנֶיךָ</span><br><span class=\"hw\">וְדִבַּרְתָּ בָּם</span><br><span class=\"hw\">בְּשִׁבְתְּךָ בְּבֵיתֶךָ</span><br><span class=\"hw\">וּבְלֶכְתְּךָ בַדֶּרֶךְ</span><br><span class=\"hw\" style=\"font-weight:700\">וּבְשׇׁכְבְּךָ וּבְקוּמֶךָ</span>.<br><span class=\"hw\" style=\"font-weight:700\">וּקְשַׁרְתָּם לְאוֹת עַל־יָדֶךָ</span><br><span class=\"hw\" style=\"font-weight:700\">וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ</span>.<br><span class=\"hw\" style=\"font-weight:700\">וּכְתַבְתָּם עַל־מְזֻזוֹת</span><br><span class=\"hw\" style=\"font-weight:700\">בֵּיתֶךָ וּבִשְׁעָרֶיךָ</span>.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Repeat them to your children and speak them when you sit at home and when you walk on the street, when you lie down and when you get up. Tie them as a sign on your hand, and let them be a symbol between your eyes. Write them on the doorposts of your house and on your gates.</div><div class=\"box dots\">○●○</div></div>\n<div class=\"slide\" id=\"s-vahavta-3\"><div class=\"box h-he he\">וְאָהַבְתָּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">V’ahavta</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">L’maan tizk’ru vaasitem<br>et kol mitzvotai,<br>vih’yitem k’doshim<br>l’Eloheichem.<br>Ani Adonai Eloheichem,<br>asher hotzeiti etchem<br>mei-eretz Mitzrayim<br>lih’yot lachem l’Elohim.<br>Ani Adonai Eloheichem.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">לְמַעַן תִּזְכְּרוּ וַעֲשִׂיתֶם</span><br><span class=\"hw\">אֶת־כׇּל־מִצְוֹתָי,</span><br><span class=\"hw\">וִהְיִיתֶם קְדֹשִׁים</span><br><span class=\"hw\">לֵאלֹהֵיכֶם.</span><br><span class=\"hw\">אֲנִי יְיָ אֱלֹהֵיכֶם,</span><br><span class=\"hw\">אֲשֶׁר הוֹצֵאתִי אֶתְכֶם</span><br><span class=\"hw\">מֵאֶרֶץ מִצְרַיִם</span><br><span class=\"hw\">לִהְיוֹת לָכֶם לֵאלֹהִים.</span><br><span class=\"hw\">אֲנִי יְיָ אֱלֹהֵיכֶם.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">In this way, you will remember and do all My mitzvot, and you will be holy to your God. I am Adonai your God who brought you out of the land of Egypt to be your God. I am Adonai your God.</div><div class=\"box dots\">○○●</div></div>\n<div class=\"slide\" id=\"s-michamocha-1\"><div class=\"box h-he he\">מִי כָמֹכָה</div><div class=\"box h-en\"><span style=\"font-weight:700\">Mi Chamochah</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.12)\">Mi chamochah ba-eilim, Adonai!<br>Mi kamochah nedar bakodesh,<br>nora t'hilot, oseih fele!</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.12)\"><span class=\"hw\">מִי־כָמֹכָה בָּאֵלִם יְיָ!</span><br><span class=\"hw\">מִי כָּמֹכָה נֶאְדָּר בַּקֹּדֶשׁ,</span><br><span class=\"hw\">נוֹרָא תְהִלֹּת, עֹשֵׂה פֶלֶא!</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*27.99);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Who is like You, O God, among the gods that are worshiped? <br>Who is like You, majestic in holiness, awesome in splendor, working wonders?</div></div>\n<div class=\"slide\" id=\"s-avot-1\"><div class=\"box h-he he\">אָבוֹת וְאִמָּהוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: Avot v’Imahot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Adonai s’fatai tiftach,<br>ufi yagid t’hilatecha.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">אֲדֹנָי שְׂפָתַי תִּפְתָּח,</span><br><span class=\"hw\">וּפִי יַגִּיד </span><span class=\"hw\">תְּהִלָּתֶך</span><span class=\"hw\">ָ.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Adonai, open up my lips, that my mouth may declare Your praise. </div><div class=\"box dots\">●○○○</div></div>\n<div class=\"slide\" id=\"s-avot-2\"><div class=\"box h-he he\">אָבוֹת וְאִמָּהוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: Avot v’Imahot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Baruch atah, Adonai,<br>Eloheinu v’Elohei<br>avoteinu v’imoteinu: <br>Elohei Avraham,<br>Elohei Yitzchak,<br>v’Elohei Yaakov,<br>Elohei Sarah, Elohei Rivkah,<br>Elohei Rachel, v’Elohei Leah.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">אֱלֹהֵינוּ </span><span class=\"hw\">וֵאלֹהֵי</span><br><span class=\"hw\">אֲבוֹתֵינוּ וְאִמּוֹתֵינוּ:</span><br><span class=\"hw\">אֱלֹהֵי</span><span class=\"hw\"> אַבְרָהָם,</span><br><span class=\"hw\">אֱלֹהֵי יִצְחָק,</span><br><span class=\"hw\">וֵאלֹהֵי יַעֲקֹב,</span><br><span class=\"hw\">אֱלֹהֵי שָׂרָה, אֱלֹהֵי רִבְקָה,</span><br><span class=\"hw\">אֱלֹהֵי רָחֵל, וֵאלֹהֵי לֵאָה.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Blessed are You, Adonai our God, God of our fathers and our mothers: God of Abraham, God of Isaac, and God of Jacob, God of Sarah, God of Rebecca, God of Rachel, and God of Leah.</div><div class=\"box dots\">○●○○</div></div>\n<div class=\"slide\" id=\"s-avot-3\"><div class=\"box h-he he\">אָבוֹת וְאִמָּהוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: Avot v’Imahot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">HaEl hagadol hagibor<br>v’hanora, El elyon,<br>gomeil chasadim tovim,<br>v’koneih hakol,<br>v’zocheir chasdei avot v’imahot,<br>umeivi g’ulah livnei v’neihem<br>l’maan sh’mo b’ahavah.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">הָאֵל הַגָּדוֹל הַגִּבּוֹר</span><br><span class=\"hw\">וְהַנּוֹרָא, אֵל עֶלְיוֹן,</span><br><span class=\"hw\">גּוֹמֵל חֲסָדִים טוֹבִים,</span><br><span class=\"hw\">וְקוֹנֵה הַכֹּל,</span><br><span class=\"hw\">וְזוֹכֵר חַסְדֵי אָבוֹת וְאִמָּהוֹת,</span><br><span class=\"hw\">וּמֵבִיא גְאֻלָּה לִבְנֵי בְנֵיהֶם</span><br><span class=\"hw\">לְמַעַן שְׁמוֹ בְּאַהֲבָה.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">You are a great, mighty, powerful, and supreme God who acts with lovingkindness, creates everything, remembers the good deeds of our fathers and mothers, and with love brings redemption to their children’s children for the sake of God’s name.</div><div class=\"box dots\">○○●○</div></div>\n<div class=\"slide\" id=\"s-avot-4\"><div class=\"box h-he he\">אָבוֹת וְאִמָּהוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: Avot v’Imahot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Melech ozeir umoshia umagein.<br><br>Baruch atah, Adonai,<br>magein Avraham v’ezrat Sarah.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">מֶלֶךְ עוֹזֵר וּמוֹשִׁיעַ וּמָגֵן.</span><br><br><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">מָגֵן אַבְרָהָם וְעֶזְרַת שָׂרָה.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">You are our Ruler who helps, saves, and protects. Blessed are You, Adonai, Abraham’s Protector and Sarah’s Helper.</div><div class=\"box dots\">○○○●</div></div>\n<div class=\"slide\" id=\"s-gvurot-1\"><div class=\"box h-he he\">גְּבוּרוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: G’vurot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Atah gibor l’olam, Adonai,<br>m’chayeih hakol/meitim <br>atah, rav l’hoshia.<br><br>Mashiv haruach<br>umorid hagashem.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">אַתָּה גִּבּוֹר לְעוֹלָם אֲדֹנָי,</span><br><span class=\"hw\">מְחַיֵּה הַכֹּל/</span><span class=\"hw\">מֵתִים</span> <br><span class=\"hw\">אַתָּה,</span> <span class=\"hw\">רַב לְהוֹשִׁיעַ.</span><br><br><span class=\"hw\">מַשִּׁיב הָרוּחַ</span><br><span class=\"hw\">וּמוֹרִיד הַגֶּשֶׁם.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">You are a hero forever, God: You give life to everything and have a great ability to save. You cause wind to blow and rain to fall.</div><div class=\"box dots\">●○○</div></div>\n<div class=\"slide\" id=\"s-gvurot-2\"><div class=\"box h-he he\">גְּבוּרוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: G’vurot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">M’chalkeil chayim b’chesed,<br>m’chayeih hakol/meitim<br>b’rachamim rabim,<br>someich noflim, <br>v’rofei cholim,<br>umatir asurim,<br>um’kayeim emunato<br>lisheinei afar.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">מְכַלְכֵּל חַיִּים בְּחֶסֶד,</span><br><span class=\"hw\">מְחַיֵּה הַכֹּל/</span><span class=\"hw\">מֵתִים</span><br><span class=\"hw\">בְּרַחֲמִים </span><span class=\"hw\">רַבִּים</span>,<br><span class=\"hw\">סוֹמֵךְ </span><span class=\"hw\">נוֹפְלִים</span>, <br><span class=\"hw\">וְרוֹפֵא </span><span class=\"hw\">חוֹלִים</span>,<br><span class=\"hw\">וּמַתִּיר </span><span class=\"hw\">אֲסוּרִים</span>,<br><span class=\"hw\">וּמְקַיֵּם אֱמוּנָתוֹ</span><br><span class=\"hw\">לִישֵׁנֵי עָפָר.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">You are a God who fills life with lovingkindness, gives life to everything with great compassion, supports those who have fallen down, heals those who are sick, frees those who are bound up, and keeps faith with those who sleep in the dust.</div><div class=\"box dots\">○●○</div></div>\n<div class=\"slide\" id=\"s-gvurot-3\"><div class=\"box h-he he\">גְּבוּרוֹת</div><div class=\"box h-en\"><span style=\"font-weight:700\">Amidah: G’vurot</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Mi chamocha, baal g’vurot,<br>umi domeh lach,<br>Melech meimit um’chayeh<br>umatzmiach y’shuah?<br>V’ne-eman atah<br>l’hachayot hakol/meitim.<br>Baruch atah, Adonai,<br>m’chayeih hakol/hameitim.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">מִי כָמוֹךָ, בַּעַל גְּבוּרוֹת,</span><br><span class=\"hw\">וּמִי דּוֹמֶה </span><span class=\"hw\">לָּךְ</span>,<br><span class=\"hw\">מֶלֶךְ מֵמִית וּמְחַיֶּה</span><br><span class=\"hw\">וּמַצְמִיחַ </span><span class=\"hw\">יְשׁוּעָה</span>?<br><span class=\"hw\">וְנֶאֱמָן אַתָּה</span><br><span class=\"hw\">לְהַחֲיוֹת הַכֹּל/</span><span class=\"hw\">מֵתִים</span>.<br><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">מְחַיֵּה הַכֹּל/</span><span class=\"hw\">הַמֵּתִים</span>.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">Who is like You, Source of mighty acts? Who can compare to You, a Power who gives life <br>and causes freedom to sprout up? Faithfully, You give life to everything/revive the dead. <br>Blessed are You, Adonai, who gives life to everything/revives the dead.</div><div class=\"box dots\">○○●</div></div>\n<div class=\"slide\" id=\"s-kedushah-1\"><div class=\"box h-en\">Amidah: K’dushah</div><div class=\"box h-he he\">קְדֻשָּׁה</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">N’kadeish et shimcha baolam,<br>k’shem shemakdishim oto<br>bishmei marom,<br>kakatuv al yad n’vi-echa,<br>v’kara zeh el zeh v’amar:</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">נְקַדֵּשׁ אֶת שִׁמְךָ בָּעוֹלָם,</span><br><span class=\"hw\">כְּשֵׁם שֶׁמַּקְדִּישִׁים אוֹתוֹ</span><br><span class=\"hw\">בִּשְׁמֵי מָרוֹם,</span><br><span class=\"hw\">כַּכָּתוּב עַל יַד נְבִיאֶךָ,</span><br><span class=\"hw\">וְקָרָא זֶה אֶל זֶה וְאָמַר:</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Let us make Your name holy on earth, as it is made holy in the heavens above. As Your prophet wrote: One called to another and said:</div><div class=\"box dots\">●○○</div></div>\n<div class=\"slide\" id=\"s-kedushah-2\"><div class=\"box h-en\">Amidah: K’dushah</div><div class=\"box h-he he\">קְדֻשָּׁה</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">Kadosh, kadosh, kadosh<br>Adonai tz’vaot,<br>m’lo chol haaretz k’vodo.<br><br>Baruch k’vod Adonai mim’komo.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">קָדוֹשׁ, קָדוֹשׁ, קָדוֹשׁ</span><br><span class=\"hw\">יְיָ צְבָאוֹת,</span><br><span class=\"hw\">מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ.</span><br><br><span class=\"hw\">בָּרוּךְ כְּבוֹד יְיָ מִמְּקוֹמוֹ.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Holy, holy, holy is Adonai of all that exists! The whole earth is full of God’s glory. Blessed is the glory of Adonai, from God’s place.</div><div class=\"box dots\">○●○</div></div>\n<div class=\"slide\" id=\"s-kedushah-3\"><div class=\"box h-en\">Amidah: K’dushah</div><div class=\"box h-he he\">קְדֻשָּׁה</div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.2)\">Yimloch Adonai l’olam,<br>Elohayich Tziyon, l’dor vador,<br>hal’luyah!<br><br>Baruch atah, Adonai,<br>haEl hakadosh.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.2)\"><span class=\"hw\">יִמְלֹךְ יְיָ לְעוֹלָם,</span><br><span class=\"hw\">אֱלֹהַיִךְ צִיּוֹן, לְדֹר וָדֹר,</span><br><span class=\"hw\">הַלְלוּיָהּ!</span><br><br><span class=\"hw\">בָּרוּךְ אַתָּה יְיָ,</span><br><span class=\"hw\">הָאֵל הַקָּדוֹשׁ.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.5);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Adonai will reign forever, your God, O Zion, from generation to generation. Halleluyah! Blessed are You, Adonai, the holy God.</div><div class=\"box dots\">○○●</div></div>\n<div class=\"slide\" id=\"s-silent-1\"><div class=\"box h-he he\">תְּפִלַּת הַלֵּב</div><div class=\"box h-en\"><span style=\"font-weight:700\">Silent Prayer</span></div></div>\n<div class=\"slide\" id=\"s-oseh-1\"><div class=\"box h-he he\">עֹשֶׂה שָׁלוֹם</div><div class=\"box h-en\"><span style=\"font-weight:700\">Oseh Shalom</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Oseh shalom bimromav,<br>hu yaaseh shalom aleinu,<br>v’al kol Yisrael,<br>v’imru: Amen.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">עֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו,</span><br><span class=\"hw\">הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ,</span><br><span class=\"hw\">וְעַל כׇּל־יִשְׂרָאֵל,</span><br><span class=\"hw\">וְאִמְרוּ: אָמֵן.</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.27)\">May the One who makes peace above in heaven make peace for us, for all of Israel, for all who live on earth, and let us say: Amen.</div></div>\n<div class=\"slide\" id=\"s-aleinu-1\"><div class=\"box h-he he\">עָלֵינוּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Aleinu</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Aleinu l’shabei-ach laadon hakol,<br>lateit g’dulah<br>l’yotzeir b’reishit,<br>shelo asanu<br>k’goyei haaratzot,<br>v’lo samanu<br>k’mishp’chot haadamah.<br>Shelo sam chelkeinu kahem,<br>v’goraleinu k’chol hamonam.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">We must praise the God of all and glorify the Creator of the universe, who did not make us like the other nations of the lands, nor like the other families of the earth. You did not make our destiny like theirs.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">עָלֵינוּ לְשַׁבֵּחַ לַאֲדוֹן הַכֹּל,</span><br><span class=\"hw\">לָתֵת גְּדֻלָּה</span><br><span class=\"hw\">לְיוֹצֵר בְּרֵאשִׁית,</span><br><span class=\"hw\">שֶׁלֹּא עָשָֹנוּ</span><br><span class=\"hw\">כְּגוֹיֵי הָאֲרָצוֹת,</span><br><span class=\"hw\">וְלֹא שָׂמָנוּ</span><br><span class=\"hw\">כְּמִשְׁפְּחוֹת הָאֲדָמָה.</span><br><span class=\"hw\">שֶׁלֹּא שָׂם חֶלְקֵנוּ כָּהֶם,</span><br><span class=\"hw\">וְגֹרָלֵנוּ כְּכָל־הֲמוֹנָם.</span></div><div class=\"box dots\">●○○</div></div>\n<div class=\"slide\" id=\"s-aleinu-2\"><div class=\"box h-he he\">עָלֵינוּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Aleinu</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">Vaanachnu kor’im<br>umishtachavim umodim,<br>lifnei Melech malchei ham’lachim,<br>HaKadosh Baruch Hu.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Therefore we bend our knees, bow, and give thanks to You, Ruler of all rulers, the Holy One of Blessing.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">וַאֲנַחְנוּ כּוֹרְעִים</span><br><span class=\"hw\">וּמִשְׁתַּחֲוִים</span><span class=\"hw\"> וּמוֹדִים,</span><br><span class=\"hw\">לִפְנֵי מֶלֶךְ מַלְכֵי</span> <span class=\"hw\">הַמְּלָכִים,</span><br><span class=\"hw\">הַקָּדוֹשׁ בָּרוּךְ הוּא.</span></div><div class=\"box dots\">○●○</div></div>\n<div class=\"slide\" id=\"s-aleinu-3\"><div class=\"box h-he he\">עָלֵינוּ</div><div class=\"box h-en\"><span style=\"font-weight:700\">Aleinu</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*1.21)\">V’ne-emar:<br>V’hayah Adonai l’Melech<br>al kol haaretz,<br>bayom hahu<br>yih’yeh Adonai echad<br>ush’mo echad.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">And as it is said, “Then Adonai will rule over all the earth. On that day, Adonai will be One, and God’s name will be One.”</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*1.21)\"><span class=\"hw\">וְנֶאֱמַר:</span><br><span class=\"hw\">וְהָיָה יְיָ לְמֶלֶךְ</span><br><span class=\"hw\">עַל כָּל הָאָרֶץ,</span><br><span class=\"hw\">בַּיּוֹם הַהוּא </span><br><span class=\"hw\">יִהְיֶה</span> <span class=\"hw\">יְיָ אֶחָד </span><br><span class=\"hw\">וּשְׁמוֹ אֶחָד.</span></div><div class=\"box dots\">○○●</div></div>\n<div class=\"slide\" id=\"s-kaddish-1\"><div class=\"box h-he he\">קַדִּישׁ יָתוֹם</div><div class=\"box h-en\"><span style=\"font-weight:700\">Mourner’s Kaddish</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*0.96)\">Yitgadal v’yitkadash<br>sh’meih raba<br>b’alma di v’ra chiruteih,<br>v’yamlich malchuteih<br>b’chayeichon uv’yomeichon<br>uv’chayei d’chol beit Yisrael,<br>baagala uvizman kariv,<br>v’imru: Amen.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Exalted and hallowed be God’s great name in the world that God created, according to plan. May God’s majesty be revealed in the days of our lifetime and the life of all Israel, speedily, imminently, to which we say: Amen.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*0.96)\"><span class=\"hw\">יִתְגַּדַּל וְיִתְקַדַּשׁ</span><br><span class=\"hw\">שְׁמֵהּ רַבָּא</span><br><span class=\"hw\">בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ,</span><br><span class=\"hw\">וְיַמְלִיךְ מַלְכוּתֵהּ</span><br><span class=\"hw\">בְּחַיֵּיכוֹן</span> <span class=\"hw\">וּבְיוֹמֵיכוֹן</span><br><span class=\"hw\">וּבְחַיֵּי </span><span class=\"hw\">דְכָל</span><span class=\"hw\"> בֵּית יִשְׂרָאֵל,</span><br><span class=\"hw\">בַּעֲגָלָא וּבִזְמַן קָרִיב,</span><br><span class=\"hw\">וְאִמְרוּ אָמֵן.</span></div><div class=\"box dots\">●○○○</div></div>\n<div class=\"slide\" id=\"s-kaddish-2\"><div class=\"box h-he he\">קַדִּישׁ יָתוֹם</div><div class=\"box h-en\"><span style=\"font-weight:700\">Mourner’s Kaddish</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*0.96)\">Y’hei sh’meih raba m’varach<br>l’alam ul’almei almaya.<br>Yitbarach v’yishtabach<br>v’yitpaar v’yitromam<br>v’yitnasei v’yit’hadar<br>v’yitaleh v’yit’halal<br>sh’meih d’Kudsha<br>B’rich Hu,</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Blessed be God’s great name for all eternity. Blessed, praised, honored, exalted, extolled, glorified, adored, and lauded be the name of the Holy Blessed One,</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*0.96)\"><span class=\"hw\">יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ</span><br><span class=\"hw\">לְעָלַם וּלְעָלְמֵי עָלְמַיָּא.</span><br><span class=\"hw\">יִתְבָּרַךְ וְיִשְׁתַּבַּח</span><br><span class=\"hw\">וְיִתְפָּאַר וְיִתְרוֹמַם</span><br><span class=\"hw\">וְיִתְנַשֵּׂא וְיִתְהַדָּר</span><br><span class=\"hw\">וְיִתְעַלֶּה וְיִתְהַלָּל</span><br><span class=\"hw\">שְׁמֵהּ דְּקֻדְשָׁא</span><br><span class=\"hw\">בְּרִיךְ הוּא.</span></div><div class=\"box dots\">○●○○</div></div>\n<div class=\"slide\" id=\"s-kaddish-3\"><div class=\"box h-he he\">קַדִּישׁ יָתוֹם</div><div class=\"box h-en\"><span style=\"font-weight:700\">Mourner’s Kaddish</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*0.96)\">l’eila min kol<br>birchata v’shirata,<br>tushb’chata v’nechemata,<br>daamiran b’alma,<br>v’imru: Amen.<br>Y’hei sh’lama raba min sh’maya<br>v’chayim aleinu<br>v’al kol Yisrael,<br>v’imru: Amen.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">Beyond all earthly words and songs of blessing, praise, and comfort. To which we say: Amen. May there be abundant peace from heaven, and life, for us and all Israel. To which we say: Amen.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*0.96)\"><span class=\"hw\">לְעֵלָּא מִן כָּל</span><br><span class=\"hw\">בִּרְכָתָא וְשִׁירָתָא,</span><br><span class=\"hw\">תֻּשְׁבְּחָתָא וְנֶחֱמָתָא,</span><br><span class=\"hw\">דַּאֲמִירָן בְּעָלְמָא,</span><br><span class=\"hw\">וְאִמְרוּ אָמֵן.</span><br><span class=\"hw\">יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָּא</span><br><span class=\"hw\">וְחַיִּים עָלֵינוּ</span><br><span class=\"hw\">וְעַל כָּל יִשְׂרָאֵל,</span><br><span class=\"hw\">וְאִמְרוּ אָמֵן.</span></div><div class=\"box dots\">○○●○</div></div>\n<div class=\"slide\" id=\"s-kaddish-4\"><div class=\"box h-he he\">קַדִּישׁ יָתוֹם</div><div class=\"box h-en\"><span style=\"font-weight:700\">Mourner’s Kaddish</span></div><div class=\"box\" style=\"font-size:calc(var(--pt)*44);line-height:calc(var(--pt)*60);left:calc(var(--in)*0.45);top:calc(var(--in)*0.96)\">Oseh shalom<br>bimromav,<br>hu yaaseh shalom aleinu,<br>v’al kol Yisrael,<br>v’imru: Amen.</div><div class=\"box\" style=\"font-size:calc(var(--pt)*28);line-height:calc(var(--pt)*33.6);left:calc(var(--in)*0.45);right:calc(var(--in)*.45);white-space:normal;bottom:calc(var(--in)*0.35)\">May the One who creates peace on high bring peace to us and to all Israel. To which we say: Amen.</div><div class=\"box he\" style=\"font-size:calc(var(--pt)*48);line-height:calc(var(--pt)*60);right:calc(var(--in)*.45);text-align:right;top:calc(var(--in)*0.96)\"><span class=\"hw\">עֹשֶׂה שָׁלוֹם</span><br><span class=\"hw\">בִּמְרוֹמָיו,</span><br><span class=\"hw\">הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ,</span><br><span class=\"hw\">וְעַל כָּל יִשְׂרָאֵל,</span><br><span class=\"hw\">וְאִמְרוּ אָמֵן.</span></div><div class=\"box dots\">○○○●</div></div>";
